+        `Publish failed: ${error?.message}, waiting ${retryDelay / 1000}s before retry...`
+      );
+      await sleepFn(retryDelay);
+    }
+  }
+
+  return {
+    success: false,
+    error:
+      lastError || new Error(`Failed to publish after ${maxRetries} attempts`),
+    publishAttempts,
+  };
