+    if (result === 'success') continue;
+    if (result === 'skipped' && allowed.has(name)) {
+      console.log(`::notice::${name} skipped by its documented event/change condition.`);
+      continue;
+    }
+    failures.push(`${name}: ${result || 'missing result'}`);
+  }
